  "Enable your team to run custom experiments on dataset": "让团队能够针对以下数据集运行自定义实验：",
  ". Configure a webhook URL to trigger remote custom experiments from UI. We will send dataset info (name, id) and config to your service, which can run against the dataset and post results to Langfuse.": "。请配置 Webhook 地址。系统会发送数据集名称、ID 和配置，由你的服务执行实验并回传结果。",
