  "This endpoint uses plain HTTP: the payload and all headers — including secret headers — will be sent unencrypted. Use HTTPS for production endpoints.": "此地址使用 HTTP，请求内容及全部请求头（包括保密请求头）会以未加密方式发送。正式服务请使用 HTTPS。",
  "Default config": "默认配置",
  "Set a default config that will be sent to the remote experiment run URL. This can be modified before starting a new run. View docs for more details.": "设置发送给远程实验地址的默认配置。每次开始运行前仍可调整，详见文档。",
