  "Configure Topics": "配置主题分析",
  "These settings apply to the whole project. Choose which traces to process in Automatic processing or for each manual batch.": "设置适用于整个项目。可在自动处理或每次手动任务中选择要处理的完整执行。",
  "The connections and models used for summaries, embeddings, and clustering.": "用于生成摘要、向量计算和聚类的模型连接与型号。",
  "Facets": "分析维度",
  "Choose which questions you want answered. Five can be on.": "选择需要回答的问题，最多可启用五项。",
  "A facet is one question Topics answers for every trace, such as what the user asked for, how the run ended, or which issues came up. Answers to the same facet are clustered into topics.": "分析维度是对每次完整执行提出的一个问题，例如用户询问什么、运行如何结束、出现哪些问题。同一维度下的回答会聚成主题。",
