  "Documentation ↗": "使用文档 ↗",
  "Bring Langfuse into your terminal and AI coding agents. These tools let you and your agents read and write Langfuse data—traces, prompts, datasets, scores, and more—without leaving your development environment.": "在终端或编程智能体中读写 Langfuse 的执行记录、提示词、数据集、评分等数据，无需离开开发环境。",
  "Agent Skill": "智能体技能",
  "The Langfuse Agent Skill is an open-source skill following Anthropic's Agent Skills standard. It equips AI coding agents (Claude Code, Cursor, Windsurf) with native Langfuse capabilities and conditions them to follow best practices, so agents produce better results when it is installed.": "Langfuse 智能体技能遵循 Anthropic 的 Agent Skills 标准，为 Claude Code、Cursor、Windsurf 等编程助手提供 Langfuse 操作能力与使用指导。",
  "The Langfuse MCP server lets AI assistants and agents interact with your Langfuse data programmatically via the Model Context Protocol. It supports both read and write operations, and you can restrict it to read-only access with an allowlist. Authenticate with a project-scoped API key pair.": "Langfuse MCP 服务让 AI 助手通过模型上下文协议读写 Langfuse 数据；可用允许列表限制为只读，使用项目级 API 密钥对认证。",
  "The Langfuse CLI provides terminal access to the full Langfuse API. It wraps every API endpoint, so you can manage traces, prompts, datasets, scores, and sessions directly from your shell or scripts. It uses the same API key pair as the Langfuse SDKs.": "Langfuse CLI 可在终端或脚本中调用全部 API，管理执行记录、提示词、数据集、评分和对话，使用与 SDK 相同的 API 密钥对。",
  "Unsupported filters": "不支持的筛选条件",
