  "Ready to start your evaluator upgrade?": "开始升级评分规则？",
  "Halo will review your deprecated evaluators and suggest upgrading all of them at once.": "Halo 会检查已停用的评分规则，并建议一次性升级全部规则。",
  "Enable AI features in the other tab, then return here to start the upgrade with Halo.": "请在另一个标签页启用 AI 功能，再返回这里通过 Halo 开始升级。",
