  "Ask your organization admin to enable AI features": "请组织管理员启用 AI 功能",
  "Halo can help you upgrade all deprecated evaluators at once. An organization admin needs to enable AI features for your organization before you can use it.": "Halo 可以协助批量升级已停用的评分规则。使用前，需要组织管理员启用 AI 功能。",
  "Learn more about AI features": "了解 AI 功能",
  "You can send your admin this message:": "可将以下内容发送给管理员：",
  "Start manual upgrade": "开始手动升级",
  "Invalid header name.": "请求头名称无效。",
  "This header is set by Langfuse and cannot be customized.": "此请求头由 Langfuse 设置，无法自定义。",
  "Header names must be unique.": "请求头名称不能重复。",
  "You do not have permission to manage integrations for this project.": "你无权管理此项目的集成。",
  "Configure a project-level callout. Your users can trigger a POST to an endpoint on trace, observation, and session detail screens. This can be used to integrate with your services to trigger workflows. See the docs": "配置项目级外部调用。用户可在完整执行、执行步骤和对话详情中，触发向指定端点发送 POST 请求，接入自己的处理流程。详见文档",
  "for more info.": "。",
