  "Add Callout Endpoint": "添加外部调用端点",
  "Langfuse sends a backend JSON POST when a user clicks a web callout action.": "用户点击外部调用操作时，Langfuse 后端会发送 JSON POST 请求。",
  "View docs": "查看文档",
  "HTTP or HTTPS URL. Custom ports are allowed. The endpoint is called from the Langfuse backend.": "填写 HTTP 或 HTTPS 地址，可包含自定义端口。调用从 Langfuse 后端发出。",
  "Shows the callout action in trace, observation, and session detail headers.": "在完整执行、执行步骤和对话详情的操作区中显示此调用。",
  "Toast message": "成功提示",
  "Shown after the backend callout succeeds.": "后端调用成功后显示的提示文字。",
  "Optional headers added to the backend POST. Content-Type is set automatically. Leave values empty for existing header names to keep encrypted values.": "后端 POST 请求附带的可选请求头，Content-Type 会自动设置。已有请求头的值留空时，保留已加密保存的值。",
  "Re-enter all header values when changing the endpoint URL.": "更改端点地址时，请重新填写全部请求头值。",
