  "For": "对于",
  ", the system message and the temperature, max_tokens and top_p setting are not supported while it is in beta.": "，目前测试版本不支持系统指令及 temperature、max_tokens、top_p 参数。",
  "More info ↗": "详细说明 ↗",
  "Model name": "模型名称",
  "Temperature": "随机程度",
  "The sampling temperature. Higher values will make the output more random, while lower values will make it more focused and deterministic.": "控制回答的随机程度。数值越高，回答越随机；数值越低，回答越集中、稳定。",
  "Output token limit": "输出 Token 上限",
  "The maximum number of tokens that can be generated in the chat completion.": "本次回答最多可生成的 Token 数量。",
  "Top P": "概率采样范围（Top P）",
  "An alternative to sampling with temperature, called nucleus sampling, where the model considers the results of the tokens with top_p probability mass. So 0.1 means only the tokens comprising the top 10% probability mass are considered. We generally recommend altering this or temperature but not both.": "按累计概率选择候选词。例如 0.1 表示只考虑累计概率最高的 10%。通常只调整此项或随机程度中的一项。",
  "Max. Reasoning Tokens": "推理 Token 上限",
  "Maximum tokens for model thinking/reasoning. Set to -1 for default (auto) thinking, 0 to disable. Only supported on Gemini 2.5+ models.": "模型思考或推理可用的 Token 上限。-1 表示默认自动思考，0 表示关闭；仅 Gemini 2.5 及以上模型支持。",
