  "Choose which field groups to include in the exports. Deselect large groups (e.g. Input / Output) to reduce export size, or privacy-sensitive groups (e.g. Metadata) to avoid storing user data.": "选择导出包含的字段组。取消输入、输出等大型字段可减少文件大小；取消附加信息等敏感字段可避免保存用户数据。",
  "Trace field groups can only be set here. The public API doesn't show them, and updating field groups through the API keeps this selection.": "完整执行的字段组只能在此设置。公共 API 不显示这些字段组；通过 API 更新时会保留这里的选择。",
