  "Detect User Disagreement": "检测用户异议",
  "Detects whether the user perceives the assistant as making an error or heading in the wrong direction.": "判断用户是否认为助手出错或偏离了方向。",
  "All CAPS": "全大写字母",
  "Detect User Frustration (ALL CAPS)": "检测用户不满（全大写）",
