  "(OSS product analytics) to make Langfuse events/metrics available in your PostHog dashboards. Upon activation, all historical data from your project will be synced. After the initial sync, new data is automatically synced every hour to keep your PostHog dashboards up to date.": "（开源产品分析工具），将 Langfuse 的事件与指标接入 PostHog 仪表盘。启用后会同步项目的全部历史数据，此后每小时自动同步新增数据。",
  "1. Select an event": "1. 选择触发事件",
  "2. Define action": "2. 设置执行操作",
  "active": "已启用",
  "more": "更多",
  "Nothing to exclude yet — uncheck a value to exclude it, or select values first.": "暂无排除项。取消勾选某个值可将其排除，也可以先选择一些值。",
  "Approximate count over the active column filters and time range only. It excludes full-text search, score, and comment filters, so it can be noticeably higher than the number of matching rows.": "此估算总数只考虑当前列筛选和时间范围，不包含全文搜索、评分或评论筛选，因此可能明显高于实际匹配行数。",
  "Approximate number of matching rows for the active filters and time range, estimated with ClickHouse's HyperLogLog (typically within a few percent of the true count).": "根据当前筛选和时间范围，使用 ClickHouse 的 HyperLogLog 估算匹配行数；通常与实际数量相差几个百分点。",
  "Gateway key created": "网关密钥已创建",
  "Create gateway key": "创建网关密钥",
  "About gateway key metadata": "关于网关密钥附加信息",
  "Attached to every trace from this key, so you can filter and group by it.": "这些信息会附加到使用此密钥上报的每条完整执行记录，便于筛选和分组。",
  "All queue items processed": "全部队列条目已处理",
  "Previous item": "上一项",
