  "Analytics are built from the traces the gateway writes to its ingestion project. Turn on usage or full ingestion in Setup to see cost and usage here.": "分析数据来自网关写入上报项目的执行记录。在“设置”中启用用量或完整数据上报，即可在此查看费用与用量。",
  "Ask your organization admin to turn on usage or full ingestion for the AI Gateway to see your cost and usage here.": "请让组织管理员为 AI Gateway 启用用量或完整数据上报，即可在此查看费用与用量。",
