  "Usage instructions": "使用说明",
  "Copy the key now. It is shown only once.": "请立即复制此密钥，它只显示一次。",
  "Desktop": "桌面应用",
  "Call the gateway from your code or connect an AI tool to it. Each tab has the steps for one tool.": "从代码调用网关，或将 AI 工具连接到网关。每个页签介绍一种工具的接入步骤。",
  "Setup instructions": "接入说明",
  "List models through the OpenAI route": "通过 OpenAI 路由列出模型",
  "A model list means the gateway key and the provider credential work.": "成功列出模型，说明网关密钥和服务商凭据均有效。",
  "List models through the Anthropic route": "通过 Anthropic 路由列出模型",
  "Export the gateway host and key": "导出网关地址和密钥",
  "Log out of any existing session": "退出已有登录会话",
  "An existing Claude login sends conflicting credentials.": "已有的 Claude 登录状态会发送冲突的凭据。",
  "Point Claude Code at the gateway": "将 Claude Code 指向网关",
  "Leave ANTHROPIC_API_KEY unset.": "不要设置 ANTHROPIC_API_KEY。",
  "Start Claude Code": "启动 Claude Code",
  "Your sessions appear in Langfuse under Sessions.": "对话会显示在 Langfuse 的“对话记录”中。",
  "Open the third-party inference settings": "打开第三方推理设置",
  "Open Developer → Configure Third-Party Inference and set Inference provider to Gateway. If the Developer menu is missing, enable Developer Mode under Help → Troubleshooting.": "打开 Developer → Configure Third-Party Inference，将 Inference provider 设为 Gateway。如无 Developer 菜单，请在 Help → Troubleshooting 中启用 Developer Mode。",
  "Optional: keep your claude.ai chats": "可选：保留 claude.ai 聊天",
  "Gateway mode uses a separate profile. To keep your existing chats and sessions, turn on Claude.ai data import under Capabilities. After restarting, use Settings → Import & export.": "网关模式使用独立配置。如需保留已有聊天和会话，请在 Capabilities 中开启 Claude.ai data import。重启后使用 Settings → Import & export。",
  "Import and export docs": "导入与导出文档",
  "Set the gateway base URL": "设置网关基础地址",
  "Paste this URL exactly as shown.": "请完整粘贴此地址，不要改写。",
  "Add your gateway key": "添加网关密钥",
  "Set Credential kind to Static API key, paste your gateway key as Gateway API key, and select Bearer as the auth scheme.": "将 Credential kind 设为 Static API key，把网关密钥粘贴到 Gateway API key，验证方式选择 Bearer。",
  "Allow egress hosts": "允许访问外部主机",
  "Under Capabilities → General restrictions, we recommend adding \"*\" to Allowed egress hosts. Otherwise, Claude can't reach websites or services outside the gateway, such as GitHub, and won't ask for permission.": "在 Capabilities → General restrictions 中，建议将“*”加入 Allowed egress hosts。否则 Claude 无法访问网关以外的网站或服务（如 GitHub），也不会请求访问权限。",
  "Apply and restart": "应用并重启",
  "Test the connection, select Apply Changes, then Save & Restart. Start a new session so the egress settings apply.": "测试连接后，选择 Apply Changes，再选择 Save & Restart。请新建会话，使外部访问设置生效。",
  "Export the gateway key": "导出网关密钥",
  "Codex reads the key from this variable on every start. Add the line to your shell profile, for example ~/.zshrc, so new terminals have it too.": "Codex 每次启动都会从此变量读取密钥。可将该行加入 shell 配置文件（如 ~/.zshrc），让新终端也能读取。",
  "Add the gateway provider": "添加网关服务商",
  "Add this to ~/.codex/config.toml ($CODEX_HOME/config.toml if you set CODEX_HOME). Put model_provider next to your other top-level keys, before any [table] section, and the [model_providers.langfuse] table after them.": "将此配置加入 ~/.codex/config.toml（若设置了 CODEX_HOME，则使用 $CODEX_HOME/config.toml）。model_provider 应与其他顶层字段并列，放在所有 [table] 段之前；[model_providers.langfuse] 段放在其后。",
  "Start Codex": "启动 Codex",
  "Each turn appears in Langfuse as one trace.": "每轮交互会在 Langfuse 中显示为一条完整执行记录。",
  "Point Copilot CLI at the gateway": "将 Copilot CLI 指向网关",
  "Replace <model> with a model from your provider credential. If ~/.copilot/providers.json lists providers, it takes precedence over these variables.": "将 <model> 替换为服务商凭据下的模型。如 ~/.copilot/providers.json 已列出服务商，其中的设置优先于这些变量。",
  "Start Copilot CLI": "启动 Copilot CLI",
  "Each model call appears in Langfuse as a trace.": "每次模型调用会在 Langfuse 中显示为一条完整执行记录。",
  "GitHub Copilot app": "GitHub Copilot 应用",
  "Add a custom endpoint": "添加自定义端点",
  "Open Settings → Model providers, select Add provider, then choose Custom endpoint. Set Display name to Langfuse.": "打开 Settings → Model providers，选择 Add provider，再选 Custom endpoint，将 Display name 设为 Langfuse。",
  "Choose the wire API and add your gateway key": "选择接口协议并添加网关密钥",
  "Set Wire API to responses, paste your gateway key as API key, leave Custom headers empty, then select Add provider.": "将 Wire API 设为 responses，把网关密钥粘贴到 API key，Custom headers 留空，再选择 Add provider。",
  "Pick a model": "选择模型",
  "The models of your OpenAI provider credential appear in the model picker alongside the GitHub-hosted models. Select one to start a session.": "您的 OpenAI 服务商凭据中的模型会与 GitHub 托管模型一起显示在模型选择器中，选择一个即可开始会话。",
  "After changing the key, run opencode service restart.": "更改密钥后，请运行 opencode service restart。",
  "Add the gateway providers": "添加网关服务商",
  "Add this to ~/.config/opencode/opencode.json. Remove stored OpenCode account connections for these providers first; they take precedence.": "将此配置加入 ~/.config/opencode/opencode.json。请先删除这些服务商在 OpenCode 中保存的账号连接，因为它们具有更高优先级。",
  "Start OpenCode": "启动 OpenCode",
  "Setup instructions could not be loaded": "无法加载接入说明",
  "Your key works. Follow the docs to connect your tools.": "密钥有效。请按照文档连接工具。",
  "Notifications could not be sent": "无法发送通知",
  "Nobody was notified: the addresses you entered get no email.": "未通知任何人：所填地址不会收到邮件。",
  "Team notified": "已通知团队",
  "Gateway keys authenticate requests to the AI Gateway only. User keys are revoked when their owner leaves the organization; service account keys keep working.": "网关密钥仅用于验证发往 AI Gateway 的请求。用户密钥会在其所有者离开组织时被撤销；服务账号密钥继续有效。",
  "Your gateway keys authenticate requests to the AI Gateway only. They are revoked when you leave the organization or lose gateway access.": "您的网关密钥仅用于验证发往 AI Gateway 的请求。当您离开组织或失去网关访问权限时，密钥将被撤销。",
  "Provider credential could not be loaded": "无法加载服务商凭据",
