  "On self-hosted Langfuse, the AI Gateway runs as a separate service. Deploy it next to your Langfuse instance to configure provider credentials, models and gateway keys.": "自托管 Langfuse 的 AI Gateway 作为独立服务运行。请在 Langfuse 实例旁部署该服务，才能配置服务商凭据、模型和网关密钥。",
