  "Requests are forwarded to the provider you configure, using your credentials and on your instruction. Make sure you have a BAA with that provider before sending PHI.": "系统会按照您的指示，使用您的凭据将请求转发到所配置的服务商。发送受保护健康信息（PHI）前，请确保已与该服务商签订业务伙伴协议（BAA）。",
